import java.util.*;

/**
 * Teaching demo: flash-sale inventory holds (reserve + claim).
 * Part 1 shows the BROKEN dual-system design: reservation counter in a
 * key-value store plus the ledger in a relational database share no commit,
 * so a crash between the two steps oversells in one order and undersells
 * in the other. Part 2 shows the FIX: a bounded pool of one-row-per-unit
 * consumed with SKIP-LOCKED semantics, refilled by a single refiller,
 * with reserve and claim in ONE local transaction.
 * Deterministic: fixed buyers, fixed payment outcomes, threads joined.
 */
public class PoolSim {
    static int passed = 0, failed = 0;

    static void check(String name, boolean cond, String detail) {
        System.out.println((cond ? "PASS " : "FAIL ") + name + " -- " + detail);
        if (cond) passed++; else failed++;
    }

    // ---------- Part 1: dual-system claim, crash between the two steps ----------
    static class DualSystem {
        int kvReserved = 0;   // key-value counter (DECR on reserve, INCR on release)
        int ledgerQty;        // relational ledger, source of truth
        DualSystem(int qty) { ledgerQty = qty; }
        void reserve(int n) { kvReserved += n; }
        // order A: deduct ledger first, then clear reservation (crash in between)
        void claimOrderA_crashAfterDeduct(int n) { ledgerQty -= n; /* crash: kvReserved never cleared */ }
        // order B: clear reservation first, then deduct ledger (crash in between)
        void claimOrderB_crashAfterClear(int n) { kvReserved -= n; /* crash: ledger never deducted */ }
    }

    // ---------- Part 2: single-database bounded pool ----------
    static class Pool {
        final LinkedList<Integer> available = new LinkedList<Integer>();
        final Set<Integer> reserved = new HashSet<Integer>();
        int ledgerQty;                 // same database as the pool
        int claimed = 0;
        boolean refilling = false;     // single-refiller guard
        int nextId = 0;
        Pool(int ledger) { ledgerQty = ledger; refill(); }
        // refill up to cap from the ledger; only one transaction does this
        synchronized void refill() {
            if (refilling) return;
            refilling = true;
            try {
                while (available.size() < 1000 && ledgerQty > 0) {
                    available.add(nextId++);
                    ledgerQty--;
                }
            } finally { refilling = false; }
        }
        // SKIP LOCKED: take up to n rows without waiting (synchronized = atomic take)
        synchronized List<Integer> reserve(int n) {
            List<Integer> got = new ArrayList<Integer>();
            while (got.size() < n && !available.isEmpty())
                got.add(available.removeFirst());
            for (int u : got) reserved.add(u);
            return got;
        }
        // claim or release inside the SAME local transaction as the ledger move
        synchronized void claim(List<Integer> units) {
            for (int u : units) reserved.remove(u);
            claimed += units.size();   // ledger row moved atomically with pool rows
        }
        synchronized void release(List<Integer> units) {
            for (int u : units) { reserved.remove(u); available.addLast(u); }
        }
        synchronized int total() { return available.size() + reserved.size() + claimed + ledgerQty; }
    }

    public static void main(String[] a) throws Exception {
        // P1: order A crash -> ledger deducted AND reservation stuck = undersell
        DualSystem d1 = new DualSystem(10);
        d1.reserve(2);
        d1.claimOrderA_crashAfterDeduct(2);
        check("P1 order-A crash undersells",
                d1.ledgerQty == 8 && d1.kvReserved == 2,
                "ledger=8 but 2 units still held -> lost sale");

        // P2: order B crash -> paid units never deducted = oversell
        DualSystem d2 = new DualSystem(10);
        d2.reserve(2);
        d2.claimOrderB_crashAfterClear(2);
        check("P2 order-B crash oversells",
                d2.ledgerQty == 10 && d2.kvReserved == 0,
                "ledger still 10, units gone -> sold air");

        // P3..P5: fixed pool, 50 buyers x 3 units, even buyers pay, odd release
        final Pool p = new Pool(5000);
        final int initial = p.total();
        final List<String> errors = Collections.synchronizedList(new ArrayList<String>());
        Thread[] ts = new Thread[50];
        for (int i = 0; i < 50; i++) {
            final int id = i;
            ts[i] = new Thread(new Runnable() {
                public void run() {
                    List<Integer> got = p.reserve(3);
                    if (got.size() != 3) { errors.add("buyer " + id + " short"); return; }
                    try { Thread.sleep(1); } catch (InterruptedException e) { errors.add("interrupt"); return; }
                    if (id % 2 == 0) p.claim(got); else p.release(got);
                }
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        check("P3 no buyer short", errors.isEmpty(), errors.isEmpty() ? "50x3 units dealt" : errors.toString());
        check("P4 conservation", p.total() == initial,
                "total=" + p.total() + " initial=" + initial);
        check("P5 claimed exact", p.claimed == 25 * 3,
                "claimed=" + p.claimed + " expected=75");

        // P6: empty pool means wait-and-refill, never a false sold-out
        final Pool small = new Pool(5);
        List<Integer> all = small.reserve(5);
        List<Integer> none = small.reserve(1);
        small.refill(); // single refiller tops up from the ledger (nothing left here)
        check("P6 empty pool honest", all.size() == 5 && none.isEmpty() && small.total() == 5,
                "drained=5 then 0, total still 5");

        System.out.println("----");
        System.out.println("checks run=" + (passed + failed) + " passed=" + passed + " failed=" + failed);
    }
}
